ws_run_block 19 'Creating the AgentCore Runtime' '2. Create the AgentCore Runtime, or update it to the new image if it exists:' 522 543 'bash' '' 300 <<'WS_TEST_BLOCK_920_19'
ECR_URI="${ACCOUNT_ID}.dkr.ecr.${AWS_REGION}.amazonaws.com/backoffice"
ROLE_ARN="arn:aws:iam::${ACCOUNT_ID}:role/backoffice-role"

RUNTIME_CONFIG=(
  --role-arn "${ROLE_ARN}"
  --agent-runtime-artifact "{\"containerConfiguration\":{\"containerUri\":\"${ECR_URI}:latest\"}}"
  --protocol-configuration '{"serverProtocol":"MCP"}'
  --network-configuration "{\"networkMode\":\"VPC\",\"networkModeConfig\":{\"subnets\":[\"${SUBNET_ID}\"],\"securityGroups\":[\"${SG_ID}\"]}}"
  --authorizer-configuration "{\"customJWTAuthorizer\":{\"discoveryUrl\":\"${GATEWAY_DISCOVERY_URL}\",\"allowedClients\":[\"${GATEWAY_CLIENT_ID}\"]}}"
  --region ${AWS_REGION} --no-cli-pager
)

MCP_RUNTIME_ID=$(aws bedrock-agentcore-control list-agent-runtimes --region ${AWS_REGION} --no-cli-pager \
  --query "agentRuntimes[?agentRuntimeName=='backoffice'].agentRuntimeId | [0]" --output text)
if [ "${MCP_RUNTIME_ID}" = "None" ]; then
  MCP_RUNTIME_ID=$(aws bedrock-agentcore-control create-agent-runtime --agent-runtime-name "backoffice" \
    "${RUNTIME_CONFIG[@]}" --query 'agentRuntimeId' --output text)
else
  aws bedrock-agentcore-control update-agent-runtime --agent-runtime-id "${MCP_RUNTIME_ID}" \
    "${RUNTIME_CONFIG[@]}" > /dev/null
fi
echo "export MCP_RUNTIME_ID=${MCP_RUNTIME_ID}" >> ~/environment/.envrc
WS_TEST_BLOCK_920_19

