ws_run_block 54 'Creating the AgentCore Runtime' '- 16-22: A new runtime is named aiagent; an existing one gets a new version with the image you just pushed' 2380 2412 'bash' 'java-spring-ai' <<'WS_TEST_BLOCK_1000_54'
source ~/environment/.envrc
ECR_URI="${ACCOUNT_ID}.dkr.ecr.${AWS_REGION}.amazonaws.com/aiagent"

RUNTIME_CONFIG=(
  --role-arn "arn:aws:iam::${ACCOUNT_ID}:role/aiagent-runtime-role"
  --agent-runtime-artifact "{\"containerConfiguration\":{\"containerUri\":\"${ECR_URI}:latest\"}}"
  --authorizer-configuration "{\"customJWTAuthorizer\":{\"discoveryUrl\":\"${AIAGENT_DISCOVERY_URL}\",\"allowedClients\":[\"${AIAGENT_CLIENT_ID}\"]}}"
  --request-header-configuration '{"requestHeaderAllowlist":["Authorization"]}'
  --network-configuration "{\"networkMode\":\"VPC\",\"networkModeConfig\":{\"subnets\":[\"${SUBNET_ID}\"],\"securityGroups\":[\"${SG_ID}\"]}}"
  --region ${AWS_REGION} --no-cli-pager
)
runtime_env() {  # runtime_env RUNTIME_ID: the application configuration and the ADOT exporter settings as JSON
  jq -n --arg id "$1" --arg region "${AWS_REGION}" --arg account "${ACCOUNT_ID}" \
    --arg memory "${AGENTCORE_MEMORY_ID}" --arg kb "${KNOWLEDGE_BASE_ID}" --arg gateway "${GATEWAY_URL}" \
    --arg issuer "${COGNITO_ISSUER_URI}" --arg bucket "${ARTIFACTS_BUCKET}" --arg portal "${PORTAL_URL}" '
    "/aws/bedrock-agentcore/runtimes/\($id)-DEFAULT" as $group | {AGENTCORE_MEMORY_ID: $memory, KNOWLEDGE_BASE_ID: $kb,
    GATEWAY_URL: $gateway, COGNITO_ISSUER_URI: $issuer, ARTIFACTS_BUCKET: $bucket, PORTAL_URL: $portal,
    OTEL_EXPORTER_OTLP_TRACES_ENDPOINT: "https://xray.\($region).amazonaws.com/v1/traces",
    OTEL_EXPORTER_OTLP_TRACES_HEADERS: "x-aws-log-group=\($group),x-aws-log-stream=spans",
    OTEL_RESOURCE_ATTRIBUTES: "service.name=aiagent.DEFAULT,aws.service.type=gen_ai_agent,deployment.environment.name=bedrock-agentcore:default,aws.log.group.names=\($group),aws.log.stream.names=otel-rt-logs,cloud.resource_id=arn:aws:bedrock-agentcore:\($region):\($account):runtime/\($id)/runtime-endpoint/DEFAULT:DEFAULT"}'
}

AIAGENT_RUNTIME_ID=$(aws bedrock-agentcore-control list-agent-runtimes --region ${AWS_REGION} --no-cli-pager \
  --query "agentRuntimes[?agentRuntimeName=='aiagent'].agentRuntimeId | [0]" --output text)
if [ "${AIAGENT_RUNTIME_ID}" = "None" ]; then
  AIAGENT_RUNTIME_ID=$(aws bedrock-agentcore-control create-agent-runtime --agent-runtime-name "aiagent" \
    "${RUNTIME_CONFIG[@]}" --environment-variables "$(runtime_env new)" --query 'agentRuntimeId' --output text)
  until [ "$(aws bedrock-agentcore-control get-agent-runtime --agent-runtime-id "${AIAGENT_RUNTIME_ID}" \
    --region ${AWS_REGION} --no-cli-pager --query 'status' --output text)" != "CREATING" ]; do sleep 5; done
fi
aws bedrock-agentcore-control update-agent-runtime --agent-runtime-id "${AIAGENT_RUNTIME_ID}" \
  "${RUNTIME_CONFIG[@]}" --environment-variables "$(runtime_env "${AIAGENT_RUNTIME_ID}")" > /dev/null
echo "export AIAGENT_RUNTIME_ID=${AIAGENT_RUNTIME_ID}" >> ~/environment/.envrc
