ws_run_block 69 'Creating the CloudFront distribution' 'Create an OAI so CloudFront can read from the private S3 bucket, set the bucket policy, and create the distribution:' 2703 2781 'bash' '' 300 <<'WS_TEST_BLOCK_1000_69'
OAI_ID=$(aws cloudfront list-cloud-front-origin-access-identities --no-cli-pager \
  --query "CloudFrontOriginAccessIdentityList.Items[?Comment=='OAI for aiagent UI'].Id | [0]" --output text)
if [ "${OAI_ID}" = "None" ]; then
  OAI_ID=$(aws cloudfront create-cloud-front-origin-access-identity \
    --cloud-front-origin-access-identity-config \
      "{\"CallerReference\":\"aiagent-$(date +%s)\",\"Comment\":\"OAI for aiagent UI\"}" \
    --no-cli-pager --query 'CloudFrontOriginAccessIdentity.Id' --output text)
fi

OAI_CANONICAL=$(aws cloudfront get-cloud-front-origin-access-identity --id "${OAI_ID}" \
  --no-cli-pager --query 'CloudFrontOriginAccessIdentity.S3CanonicalUserId' --output text)

cat > /tmp/bucket-policy.json << EOF
{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Allow",
    "Principal": {"CanonicalUser": "${OAI_CANONICAL}"},
    "Action": "s3:GetObject",
    "Resource": "arn:aws:s3:::${UI_BUCKET}/*"
  }]
}
EOF

aws s3api put-bucket-policy --bucket "${UI_BUCKET}" \
  --policy file:///tmp/bucket-policy.json --no-cli-pager

cat > /tmp/cf-distribution.json << EOF
{
  "CallerReference": "aiagent-$(date +%s)",
  "Comment": "aiagent UI",
  "Enabled": true,
  "DefaultRootObject": "index.html",
  "Origins": {
    "Quantity": 1,
    "Items": [{
      "Id": "S3-${UI_BUCKET}",
      "DomainName": "${UI_BUCKET}.s3.${AWS_REGION}.amazonaws.com",
      "S3OriginConfig": {
        "OriginAccessIdentity": "origin-access-identity/cloudfront/${OAI_ID}"
      }
    }]
  },
  "DefaultCacheBehavior": {
    "TargetOriginId": "S3-${UI_BUCKET}",
    "ViewerProtocolPolicy": "redirect-to-https",
    "AllowedMethods": {
      "Quantity": 2,
      "Items": ["GET", "HEAD"],
      "CachedMethods": {"Quantity": 2, "Items": ["GET", "HEAD"]}
    },
    "ForwardedValues": {"QueryString": false, "Cookies": {"Forward": "none"}},
    "MinTTL": 0,
    "DefaultTTL": 86400,
    "MaxTTL": 31536000,
    "Compress": true
  },
  "CustomErrorResponses": {
    "Quantity": 1,
    "Items": [{
      "ErrorCode": 403,
      "ResponsePagePath": "/index.html",
      "ResponseCode": "200",
      "ErrorCachingMinTTL": 300
    }]
  },
  "PriceClass": "PriceClass_100"
}
EOF

UI_DOMAIN=$(aws cloudfront list-distributions --no-cli-pager \
  --query "DistributionList.Items[?Origins.Items[0].DomainName=='${UI_BUCKET}.s3.${AWS_REGION}.amazonaws.com'].DomainName | [0]" \
  --output text)
if [ "${UI_DOMAIN}" = "None" ]; then
  UI_DOMAIN=$(aws cloudfront create-distribution \
    --distribution-config file:///tmp/cf-distribution.json \
    --no-cli-pager --query 'Distribution.DomainName' --output text)
fi
echo "export UI_DOMAIN=${UI_DOMAIN}" >> ~/environment/.envrc
WS_TEST_BLOCK_1000_69

